package glitch

import data.glitch_lib
import future.keywords.in

credential_keywords := {"password", "pwd", "pass", "secret", "auth_token", "credential", "keystore_password", "truststore_password", "key", "token", "auth", "passwd", "sha512_password", "sha256_password", "md5_password"}

default_passwords := {"admin", "password", "123456", "default", "changeme", "root", "toor", "guest", "user", "test", "password123", "admin123", "12345678", "qwerty", "letmein", "welcome", "login", "pass", "cassandra", "telarista"}

# Check if a string indicates external/variable reference
is_external_reference(str) {
    regex.match("\\$\\{", str)
}

is_external_reference(str) {
    regex.match("(?i)secret|vault|keyvault|key.?manager|data\\.", str)
}

is_variable_reference(str) {
    regex.match("\\$\\(|\\$\\{|\\$[a-zA-Z_]|\\$\\$", str)
}

# Check if name contains credential keywords
is_credential_attribute(name) {
    lower_name := lower(name)
    some kw in credential_keywords
    regex.match(sprintf(".*%s.*", [kw]), lower_name)
}

# Check if value is a known default password
is_default_password(val_str) {
    lower_val := lower(val_str)
    default_passwords[lower_val]
}

# Check if value looks like a hardcoded password (non-empty, not external ref, not var ref)
is_hardcoded_password(val_str) {
    count(val_str) > 0
    not regex.match("^\\s*$", val_str)
    not is_external_reference(val_str)
    not is_variable_reference(val_str)
}

# Combined check for suspicious password value
looks_like_password(str_val) {
    is_hardcoded_password(str_val)
}

looks_like_password(str_val) {
    is_default_password(str_val)
}

# Check a credential pair and emit finding if it matches
check_credential_pair(key_str, val_node, path) = result {
    is_credential_attribute(key_str)
    val_node.ir_type == "String"
    val_str := val_node.value
    looks_like_password(val_str)
    result := {
        "type": "sec_hard_pass",
        "element": val_node,
        "path": path,
        "description": "Use of hard-coded password - Credentials should not be hard-coded in configuration. Use secret management services instead. (CWE-259)"
    }
}

# Recursively walk any node to find credential pairs in nested structures
# Returns [key_str, val_node] pairs
find_credential_pairs(node) = pairs {
    node.ir_type == "Hash"
    pairs := {p |
        some entry in node.value
        entry.key.ir_type == "String"
        key_str := entry.key.value
        val_node := entry.value
        is_credential_attribute(key_str)
        p := [key_str, val_node]
    } | {p |
        some entry in node.value
        more_pairs := find_credential_pairs(entry.value)
        some mp in more_pairs
        p := mp
    }
}

find_credential_pairs(node) = pairs {
    node.ir_type == "Array"
    pairs := {p |
        some elem in node.value
        some ep in find_credential_pairs(elem)
        p := ep
    }
}

find_credential_pairs(node) = pairs {
    not node.ir_type == "Hash"
    not node.ir_type == "Array"
    pairs := set()
}

# Check Variable nodes - both direct string values and nested structures
collect_variable_findings(var, path) = findings {
    var.ir_type == "Variable"
    findings := {f |
        # Direct string value with credential name
        var.value.ir_type == "String"
        some cp in {p | p := [var.name, var.value]; is_credential_attribute(var.name)}
        key_str := cp[0]
        val_node := cp[1]
        f := check_credential_pair(key_str, val_node, path)
    } | {f |
        # Nested Hash or Array values
        some pair in find_credential_pairs(var.value)
        key_str := pair[0]
        val_node := pair[1]
        f := check_credential_pair(key_str, val_node, path)
    }
}

# Check Attribute nodes - both direct string values and nested structures  
collect_attribute_findings(attr, path) = findings {
    attr.ir_type == "Attribute"
    findings := {f |
        # Direct string value with credential name
        attr.value.ir_type == "String"
        some cp in {p | p := [attr.name, attr.value]; is_credential_attribute(attr.name)}
        key_str := cp[0]
        val_node := cp[1]
        f := check_credential_pair(key_str, val_node, path)
    } | {f |
        # Nested Hash or Array values
        some pair in find_credential_pairs(attr.value)
        key_str := pair[0]
        val_node := pair[1]
        f := check_credential_pair(key_str, val_node, path)
    }
}

# Main analysis - use walk to find all potential nodes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Walk through parent and check each Variable
    some [_, node] in walk(parent)
    node.ir_type == "Variable"
    some result in collect_variable_findings(node, parent.path)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Walk through parent and check each Attribute
    some [_, node] in walk(parent)
    node.ir_type == "Attribute"
    some result in collect_attribute_findings(node, parent.path)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Direct walk through Hash entries for any nested credential
    some [_, node] in walk(parent)
    node.ir_type == "Hash"
    some entry in node.value
    entry.key.ir_type == "String"
    key_str := entry.key.value
    result := check_credential_pair(key_str, entry.value, parent.path)
}

